"""Small scanline lane tracker. Core uses only Python's standard library.

Input: upright grayscale frame exposing get_pixel(x, y), width, height.
Output signs: positive means right. No actuator commands are sent here.
"""
import math


def quadratic(points):
    """Fit x = a*t*t + b*t + c using a tiny pivoted linear solve."""
    sums = [sum(t ** k for t, x in points) for k in range(5)]
    rhs = [sum(x * t ** k for t, x in points) for k in range(3)]
    m = [[sums[i + j] for j in range(3)] + [rhs[i]] for i in range(3)]
    for i in range(3):
        pivot = max(range(i, 3), key=lambda j: abs(m[j][i]))
        m[i], m[pivot] = m[pivot], m[i]
        if abs(m[i][i]) < 1e-9:
            return None
        scale = m[i][i]
        m[i] = [v / scale for v in m[i]]
        for j in range(3):
            if j != i:
                scale = m[j][i]
                m[j] = [v - scale * w for v, w in zip(m[j], m[i])]
    return m[2][3], m[1][3], m[0][3]




"""Sparse continuous boundaries and one authoritative steering decision.
No image-wide processing. Reuses eleven rows; raw angle is image geometry.
"""
import math

# 直道右纠偏参数：左边线横坐标/画宽；更早介入，退回退出线才撤销。
RIGHT_ENTER = .22
RIGHT_EXIT = .18
RIGHT_URGENT = .38
RIGHT_CONFIRM = .08
RIGHT_SINGLE_CONFIRM = .12
WIDE_ROAD_MIN = .58
WIDE_ROAD_HISTORY_SECONDS = 1.0
WIDE_ROAD_MIN_SAMPLES = 5
NARROW_ROAD_CONFIRM_SECONDS = .45

class BoundaryTracker:
    def __init__(self, threshold=70, **kwargs):
        self.threshold=threshold
        self.counterclockwise=kwargs.get('counterclockwise',True)
        self.turn_memory_seconds=kwargs.get('turn_memory_seconds',7.0)
        self.rows=[]
        self.raw_image_angle=None
        self.last_time=None
        self.last_edges={}
        self.width_fit=None
        self.width_time=None
        self.last_full_time=None
        self.full_rows={}
        self.offset=self.heading=self.curvature=0.0
        self.state='LOST'
        self.mode='LOST'
        self.degraded=False
        self.pending=0
        self.pending_since=None
        self.position_direction=0
        self.edge_side=None
        self.edge_time=None
        self.threshold_used=threshold
        self.turn_memory_direction=0
        self.turn_memory_time=None
        self.turn_memory_angle=0.0
        # Road-shape classification is deliberately separate from steering.
        # Camera perspective makes even a straight lane look diagonally left.
        self.curve_active=False
        self.curve_pending=None
        self.curve_pending_since=None
        self.curve_time=None
        self.road_width_history=[]
        self.wide_road=False
        self.road_width_classified=False
        self.narrow_road_latched=False
        self.narrow_width_since=None

    def remember_turn(self,direction,timestamp,angle=None):
        """Remember only an independently confirmed turn, never memory itself."""
        if direction and (not self.counterclockwise or direction<0):
            self.turn_memory_direction=direction
            self.turn_memory_time=timestamp
            if angle is not None and abs(angle)>=4:
                self.turn_memory_angle=angle

    def _update_road_shape(self,evidence,timestamp,angle=None):
        """Confirm -1=left curve or 0=straight; None means insufficient view."""
        if evidence is None:
            self.curve_pending=None
            self.curve_pending_since=None
            return
        if evidence!=self.curve_pending:
            self.curve_pending=evidence
            self.curve_pending_since=timestamp
            return
        confirm=.16 if evidence<0 else .30
        if timestamp-self.curve_pending_since<confirm:return
        if evidence<0:
            self.curve_active=True
            self.curve_time=timestamp
            self.remember_turn(-1,timestamp,angle)
        else:
            self.curve_active=False
            self.curve_time=None
            self.turn_memory_direction=0
            self.turn_memory_time=None

    def _scan(self,get_pixel,y,width):
        values=[get_pixel(x,y) for x in range(width)]
        # A few samples estimate background without sorting the entire row.
        sample=sorted(values[::8])
        bg=sample[int(len(sample)*.7)]
        cutoff=0 if self.threshold==0 else min(110,max(35,int(bg*.65)))
        self.threshold_used=cutoff
        runs=[];start=None
        for x in range(width+1):
            dark=x<width and values[x]<=cutoff
            if dark and start is None:start=x
            elif not dark and start is not None:
                size=x-start
                if 2<=size<=width*.18:runs.append(((start+x-1)*.5,size))
                start=None
        return runs

    def _chains(self, rows, width):
        chains=[]
        for y,runs in rows:
            used=set()
            # Existing long paths get first choice; line-width continuity also matters.
            chains.sort(key=len,reverse=True)
            for chain in chains:
                py,px,pw=chain[-1]
                if y-py>18:continue
                slope=0
                if len(chain)>1:
                    y0,x0,_=chain[-2];slope=(px-x0)/(py-y0)
                expected=px+max(-1.2,min(1.2,slope))*(y-py)
                options=[(abs(x-expected)+abs(w-pw)*.4,i) for i,(x,w) in enumerate(runs)
                         if i not in used and abs(x-expected)<width*.12]
                if options:
                    _,i=min(options);x,w=runs[i];chain.append((y,x,w));used.add(i)
            for i,(x,w) in enumerate(runs):
                if i not in used and len(chains)<16:chains.append([(y,x,w)])
            chains=[c for c in chains if y-c[-1][0]<=18]
        strong=[]
        for chain in chains:
            if len(chain)<7 or chain[-1][0]-chain[0][0]<42:continue
            fit=quadratic([((y/120-.49)/.33,x) for y,x,_ in chain])
            if fit is None:continue
            a,b,c=fit
            error=sum(abs(x-(a*((y/120-.49)/.33)**2+b*((y/120-.49)/.33)+c)) for y,x,_ in chain)/len(chain)
            if error>2.5:continue
            strong.append((chain,fit,error))
        strong.sort(key=lambda e:(-len(e[0]),e[2]))
        return strong[:4]

    def update(self,get_pixel,width,height,timestamp,run_provider=None):
        if self.last_time is not None and timestamp<=self.last_time:raise ValueError('timestamps must increase')
        dt=0 if self.last_time is None else timestamp-self.last_time
        self.last_time=timestamp
        if dt>.25:
            self.pending=0;self.pending_since=timestamp;self.position_direction=0
        previous_mode=self.mode
        self.rows=[];self.raw_image_angle=None
        ys=[int(height*(.24+i*.056)) for i in range(11)]
        sampled=[(y,[(x,3) for x in run_provider(y)] if run_provider else self._scan(get_pixel,y,width)) for y in ys]
        edges=self._chains(sampled,width)
        def at(f,t):return f[0]*t*t+f[1]*t+f[2]
        paired=None
        for i,e in enumerate(edges):
            for other in edges[i+1:]:
                l,r=sorted((e,other),key=lambda z:at(z[1],.8))
                widths=[at(r[1],t)-at(l[1],t) for t in [-.5,0,.8]]
                if min(widths)<width*.30 or max(widths)>width*1.4:continue
                # Perspective normally widens toward feet; avoid internal marker pairs.
                if widths[-1]<widths[0]*.7:continue
                score=len(l[0])+len(r[0])+sum(widths)/width
                if paired is None or score>paired[0]:paired=(score,l,r)
        fit=None;near_left=near_right=None;confidence=0;source='NONE'
        single_curve_direction=0
        if paired:
            _,l,r=paired
            fit=tuple((a+b)*.5 for a,b in zip(l[1],r[1]))
            self.width_fit=tuple(b-a for a,b in zip(l[1],r[1]))
            self.width_time=timestamp
            self.last_full_time=timestamp
            self.last_edges={'LEFT':(l[1],timestamp),'RIGHT':(r[1],timestamp)}
            self.mode='BOTH';self.degraded=False
            near_left=at(l[1],.8);near_right=at(r[1],.8)
            near_width=near_right-near_left
            self.road_width_history=[(t,w) for t,w in self.road_width_history
                                     if timestamp-t<=WIDE_ROAD_HISTORY_SECONDS]
            self.road_width_history.append((timestamp,near_width))
            if not self.road_width_classified and len(self.road_width_history)>=WIDE_ROAD_MIN_SAMPLES:
                ordered=sorted(w for _,w in self.road_width_history)
                # 下四分位可排除摆动中偶发的宽配对；窄道不能套用直道早右纠。
                self.wide_road=ordered[len(ordered)//4]>=width*WIDE_ROAD_MIN
                self.narrow_road_latched=not self.wide_road
                self.road_width_classified=True
            elif self.road_width_classified and not self.narrow_road_latched:
                # 宽道进入窄道时要持续变窄才切换；一次摆动或错误配对不能误锁窄道。
                if near_width<width*WIDE_ROAD_MIN:
                    if self.narrow_width_since is None:self.narrow_width_since=timestamp
                    elif timestamp-self.narrow_width_since>=NARROW_ROAD_CONFIRM_SECONDS:
                        self.narrow_road_latched=True
                        self.wide_road=False
                else:
                    self.narrow_width_since=None
            confidence=min(len(l[0]),len(r[0]))/11
            self.rows=[(y,at(l[1],(y/height-.49)/.33),at(r[1],(y/height-.49)/.33)) for y in ys]
            self.full_rows={y:(l,r) for y,l,r in self.rows}
            source='PAIRED'
        elif edges:
            edge,ef,error=edges[0];near=at(ef,.8)
            # Dashes are supporting evidence only, outside the candidate on its left.
            dash_rows=sum(any(4<at(ef,(y/height-.49)/.33)-x<width*.28 and w<=4 for x,w in runs) for y,runs in sampled)
            side=None
            old=[]
            for name,(old_fit,stamp) in self.last_edges.items():
                if timestamp-stamp<.6:old.append((abs(near-at(old_fit,.8)),name))
            if old and min(old)[0]<width*.20:side=min(old)[1]
            if side is None and self.edge_time is not None and timestamp-self.edge_time<.3:
                if abs(near-self.edge_near)<width*.15:side=self.edge_side
            if side is None:
                if 2<=dash_rows<=8:side='LEFT'
                elif near<width*.40:side='LEFT'
                elif near>width*.60:side='RIGHT'
            self.degraded=True
            self.mode='SINGLE_'+side if side else 'UNCERTAIN'
            confidence=min(.65,len(edge)/11*.65) if side else .15
            if side:
                self.edge_side,self.edge_time,self.edge_near=side,timestamp,near
                self.last_edges[side]=(ef,timestamp)
                if side=='LEFT':near_left=near
                else:near_right=near
                # Width is used only while recent; never report an old angle as measured.
                if self.width_time is not None and timestamp-self.width_time<=.8:
                    sign=.5 if side=='LEFT' else -.5
                    fit=tuple(a+sign*b for a,b in zip(ef,self.width_fit))
                    source='ESTIMATED'
                # On this counter-clockwise course either edge can prove a
                # left curve. Thresholds differ because the inner/left edge is
                # seen earlier. Recorded straight left edges have negative b;
                # recorded curved left edges have a<=-3 and positive b.
                a,b,c=ef
                left_curve=(side=='RIGHT' and a<=-2 and b>=15) or \
                           (side=='LEFT' and a<=-3 and b>=2)
                if self.counterclockwise and left_curve:
                    single_curve_direction=-1
                    single_angle=math.degrees(math.atan(-b/(.33*height)))
                    self.remember_turn(-1,timestamp,
                                       self.turn_memory_angle or single_angle)
                self.rows=[(y,x,x) for y,x,w in edge]
        else:
            self.mode='LOST';self.degraded=True
        valid=self.mode not in ('LOST','UNCERTAIN')
        if fit:
            a,b,c=fit
            self.raw_image_angle=math.degrees(math.atan(-b/(.33*height)))
            alpha=1 if dt<=0 or dt>.25 else 1-math.exp(-dt/.35)
            offset=(at(fit,.8)-width*.5)/(width*.5)
            self.offset+=alpha*(offset-self.offset)
            self.heading=-b/(width*.5)
            self.curvature=a/(width*.5)
            # Thresholds measured from two all-straight and two all-left-curve
            # recordings. Both terms are needed: curvature rejects perspective,
            # while heading rejects small quadratic fit noise on straight edges.
            if self.curvature<=-.018 and self.heading<=-.09:
                self._update_road_shape(-1,timestamp,self.raw_image_angle)
            # Leave a confirmed curve only when the fitted edge itself becomes
            # nearly straight. Heading alone is perspective-dependent.
            elif self.curvature>=-.012:
                self._update_road_shape(0,timestamp,self.raw_image_angle)
            else:
                self._update_road_shape(None,timestamp)
        elif single_curve_direction:
            self._update_road_shape(-1,timestamp,self.turn_memory_angle)
        else:
            self._update_road_shape(None,timestamp)
        # Position escape has precedence over image-heading correction.
        aggressive_right=self.wide_road and self.mode=='BOTH'
        right_enter=RIGHT_ENTER if aggressive_right else .34
        right_exit=RIGHT_EXIT if aggressive_right else .28
        wanted=0
        if valid:
            if self.mode=='SINGLE_LEFT' and near_left>width*(right_exit if self.position_direction==1 else right_enter):wanted=1
            elif self.mode=='SINGLE_RIGHT' and near_right<width*.72:wanted=-1
            elif self.mode=='BOTH':
                if near_left>width*(right_exit if self.position_direction==1 else right_enter):wanted=1
                elif near_right<width*.66:wanted=-1
                elif self.position_direction==1 and near_left>width*right_exit:wanted=1
                elif self.position_direction==-1 and near_right<width*.72:wanted=-1
        # 同方向单双边切换不重置右纠确认；丢线/反向仍重置。
        if self.mode!=previous_mode and not (aggressive_right and wanted==1 and self.pending==1):
            self.position_direction=0
            self.pending=0
            self.pending_since=timestamp
        if wanted!=self.pending:
            self.pending=wanted;self.pending_since=timestamp
        if not valid or not wanted:self.position_direction=0
        elif wanted==1:
            confirm=RIGHT_CONFIRM if aggressive_right else (.4 if self.degraded else .2)
            if timestamp-self.pending_since>=confirm:self.position_direction=1
        elif timestamp-self.pending_since>=(.4 if self.degraded else .2):self.position_direction=wanted
        urgent_right=bool(aggressive_right and valid and near_left is not None and near_left>width*RIGHT_URGENT
                          and self.position_direction==1)
        remembered_direction=0
        if (valid and self.mode=='SINGLE_RIGHT' and
                self.turn_memory_direction<0 and self.turn_memory_time is not None and
                timestamp-self.turn_memory_time<=self.turn_memory_seconds):
            remembered_direction=self.turn_memory_direction
        curve_direction=0
        if (self.curve_active and self.curve_time is not None and
                timestamp-self.curve_time<=self.turn_memory_seconds):
            curve_direction=-1
        self.state=('RIGHT' if self.position_direction>0 else 'LEFT') if self.position_direction else 'STRAIGHT' if valid else 'LOST'
        # 正误差=靠左，要减少左转/向右纠偏；负误差=靠右，要增加左转。
        # 边线位置换算为控制等效角，不是相机朝向角。安全区内误差为0。
        position_error_deg=0.0
        if valid:
            if self.mode in ('BOTH','SINGLE_LEFT') and near_left>width*right_exit:
                position_error_deg=min(15.0,(near_left/width-right_exit)*60.0)
            elif self.mode in ('BOTH','SINGLE_RIGHT') and near_right<width*.72:
                position_error_deg=max(-15.0,(near_right/width-.72)*60.0)
        return dict(valid=valid,stop=not valid,state=self.state,confidence=confidence,
                    position_error_deg=position_error_deg,urgent_right=urgent_right,
                    wide_road=self.wide_road,aggressive_right=aggressive_right,
                    degraded=self.degraded,offset=self.offset,heading=self.heading,curvature=self.curvature,
                    steer=self.position_direction,mode=self.mode,angle_source=source,
                    position_direction=self.position_direction,
                    remembered_direction=remembered_direction,
                    remembered_angle=self.turn_memory_angle,
                    single_curve_direction=single_curve_direction,
                    curve_direction=curve_direction,
                    road_shape='LEFT_CURVE' if curve_direction else 'STRAIGHT')


def resolve_control(lane,angle):
    """Both outgoing packets and the display use this same decision."""
    out=dict(angle)
    position=lane.get('position_direction',0)
    if not lane['valid'] and lane.get('curve_direction',0):
        # A short occlusion inside an already confirmed left curve must not
        # cancel the turn. This cannot start a turn from a straight/lost frame.
        direction=lane['curve_direction']
        remembered_angle=lane.get('remembered_angle',0.0)
        out.update(valid=True,active=True,direction=direction,angle=remembered_angle,
                   status=3,
                   reason='LOSS_HOLD')
    elif not lane['valid']:
        out.update(valid=False,active=False,direction=0,angle=0.0,status=0,reason='NO_EDGE')
    elif position>0 and lane.get('urgent_right',False):
        # 已确认贴近左边线：双边可见时也优先右避边。
        out.update(valid=True,active=True,direction=1,angle=0.0,status=4,reason='POSITION')
    elif position and lane.get('mode')!='BOTH':
        # With only one edge visible, escaping the nearby boundary is safest.
        out.update(valid=True,active=True,direction=position,angle=0.0,
                   status=4 if position>0 else 3,reason='POSITION')
    elif lane.get('curve_direction',0):
        direction=lane['curve_direction']
        curve_angle=angle.get('angle',0.0) if angle.get('valid') else lane.get('remembered_angle',0.0)
        out.update(valid=True,active=True,direction=direction,angle=curve_angle,
                   status=3,reason='CURVE')
    elif position:
        out.update(valid=True,active=True,direction=position,angle=0.0,
                   status=4 if position>0 else 3,reason='POSITION')
    elif lane.get('remembered_direction',0):
        direction=lane['remembered_direction']
        remembered_angle=lane.get('remembered_angle',0.0)
        out.update(valid=True,active=True,direction=direction,angle=remembered_angle,
                   status=3,
                   reason='TURN_MEMORY')
    else:
        # A straight road uses only lateral position correction. Its perspective
        # angle must never be converted into a turn command.
        out.update(valid=True,active=False,direction=0,angle=0.0,status=1,reason='STRAIGHT')
    # 弯道、转弯记忆和短时丢线必须保留真实转角；只有位置避边使用位置误差角。
    if out.get('reason')=='POSITION' and out['status'] in (3,4) and 'position_error_deg' in lane:
        out['angle']=lane['position_error_deg'] if out['status']==3 else max(0.0,lane['position_error_deg'])
    lane=dict(lane)
    if out.get('reason')=='LOSS_HOLD':
        lane['valid']=True;lane['stop']=False
    lane['state']=('RIGHT' if out['direction']>0 else 'LEFT') if out['active'] else 'STRAIGHT' if lane['valid'] else 'LOST'
    return lane,out


LaneTracker = BoundaryTracker


"""Image heading, positive = lane right / rightward correction, not body yaw."""
import math

class AngleTracker:
    def __init__(self, enter=8.0, leave=4.0, confirm=.2, tau=.35, zero=0.0):
        self.enter, self.leave, self.confirm = enter, leave, confirm
        self.tau, self.zero = tau, zero
        self.reset()

    def reset(self):
        self.history = []
        self.filtered = self.last = None
        self.active = self.pending = 0
        self.since = None

    def update(self, raw, timestamp):
        if raw is None or not math.isfinite(raw):
            self.reset()
            return dict(valid=False, active=False, angle=0.0, direction=0)
        if self.last is not None and timestamp-self.last > .25:
            self.reset()
        self.history = [(t,v) for t,v in self.history if timestamp-t <= .1]
        self.history.append((timestamp,raw-self.zero))
        values = sorted(v for _,v in self.history)
        n=len(values)
        median=(values[(n-1)//2]+values[n//2])*.5
        if self.filtered is None:
            self.filtered=median
        else:
            self.filtered += (1-math.exp(-(timestamp-self.last)/self.tau))*(median-self.filtered)
        self.last=timestamp
        angle=self.filtered
        direction=1 if angle>0 else -1
        if self.active and (abs(angle)<=self.leave or direction!=self.active):
            self.active=0
        candidate=direction if abs(angle)>self.enter else 0
        if self.active:
            self.pending=0
            self.since=None
        elif not candidate:
            self.pending=0
            self.since=None
        elif candidate!=self.pending:
            self.pending=candidate
            self.since=timestamp
        elif timestamp-self.since>=self.confirm:
            self.active=candidate
            self.pending=0
            self.since=None
        return dict(valid=True, active=bool(self.active), angle=angle, direction=self.active)


"""7 bytes: AA 55 sequence command shape CRC16-CCITT-FALSE (little endian).

Commands: 0 stop/lost, 1 forward, 2 left, 3 right.
Shape: 0 none, 1 circle, 2 star, 3 square, 4 diamond, 5 plus, 6 triangle.
The legacy packet has no angle. Additional AA56 packets carry unified control.
"""
import struct


def crc16(data):
    crc = 0xffff
    for value in data:
        crc ^= value << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xffff if crc & 0x8000 else (crc << 1) & 0xffff
    return crc


def encode(result, sequence, shape_id=0):
    if shape_id not in (0, 1, 2, 3, 4, 5, 6):
        raise ValueError("shape_id must be 0..6")
    commands = {"LOST": 0, "STRAIGHT": 1, "LEFT": 2, "RIGHT": 3}
    command = commands[result["state"]] if result["valid"] and not result["stop"] else 0
    body = bytes((0xaa, 0x55, sequence & 255, command, shape_id))
    return body + struct.pack("<H", crc16(body))


def encode_angle(result, sequence):
    """8 bytes AA 56 seq status int16_deci_degrees crc16, little endian.
    status 0=invalid, 1=no adjustment, 2=generic angle,
    3=left turn/left correction with optional signed angle,
    4=right correction, 5=wait for board.
    For status 3: negative angle increases left turn, positive reduces it;
    zero asks the STM32 to use its default 2090 target.
    """
    status = result.get('status', 0 if not result['valid'] else 2 if result['active'] else 1)
    value = int(round(result['angle']*10)) if status in (2,3,4) else 0
    value = max(-900, min(900, value))
    body = bytes((0xaa,0x56,sequence & 255,status))+struct.pack('<h',value)
    return body+struct.pack('<H',crc16(body))


def encode_obstacle(result, sequence):
    """8 bytes AA 58 seq flags int16 bar-angle-in-0.1deg CRC16."""
    present=1 if result.get('present') else 0
    value=int(round(result.get('angle',0.0)*10)) if present else 0
    value=max(-450,min(450,value))
    body=bytes((0xaa,0x58,sequence & 255,present))+struct.pack('<h',value)
    return body+struct.pack('<H',crc16(body))



"""Optional UART feedback. No RX pin => open-loop, no fabricated step completion."""

class MotionFeedback:
    def __init__(self, enabled=False, continuous_control=False):
        self.enabled=enabled
        self.continuous_control=continuous_control
        self.buffer=bytearray()
        self.pending=None
        self.ready=not enabled
        self.sent_at=None
        self.settle_until=0
        self.reset_heading=False
        self.fault=False
        self.link_established=not enabled
        self.start_time=0.0
        self.action_timeout=12.0
        # Any CRC-valid AA57 proves the UART link is alive.  Keep this
        # separate from last_rx, which is intentionally stricter and only
        # advances the motion-feedback state machine on an applicable reply.
        self.last_link_rx=None
        self.last_rx=None
        self.last_state=None
        self.last_seq=None
        self.valid_packets=0
        self.bad_packets=0
        self.rx_bytes=0

    def feed(self,data,now):
        if not data:return
        self.rx_bytes+=len(data)
        self.buffer.extend(data)
        # K230 CanMV MicroPython does not support deleting bytearray items.
        if len(self.buffer)>128:self.buffer=bytearray(self.buffer[-128:])
        while len(self.buffer)>=6:
            if self.buffer[0]!=0xaa or self.buffer[1]!=0x57:
                self.bad_packets+=1
                self.buffer=bytearray(self.buffer[1:]);continue
            packet=self.buffer[:6]
            if packet[3]>3 or crc16(packet[:4])!=(packet[4]|packet[5]<<8):
                self.bad_packets+=1
                self.buffer=bytearray(self.buffer[1:]);continue
            self.buffer=bytearray(self.buffer[6:])
            seq,state=packet[2],packet[3]
            self.valid_packets+=1
            self.last_link_rx=now
            self.last_seq=seq
            self.last_state=state
            if state==0:
                # READY is a one-shot startup handshake, not a heartbeat.
                self.link_established=True
                self.pending=None;self.fault=False;self.ready=True;self.last_rx=now
            elif self.pending==seq:
                self.last_rx=now
                if state==1:self.ready=False
                elif state==2:
                    self.pending=None;self.fault=False;self.ready=True;self.settle_until=now+.15
                    self.reset_heading=True
                elif state==3:self.fault=True;self.ready=False
            elif state==3:
                self.fault=True;self.ready=False

    def link_status(self,now):
        if not self.enabled:return 'OFF'
        if self.fault:return 'FAULT'
        if not self.link_established:return 'WAIT' if now-self.start_time<=3.0 else 'FAULT'
        return 'OK'

    def gate(self,lane,control,now):
        if not self.enabled:return lane,control
        # 主板已按完整步锁存方向，反馈仅作诊断。丢反馈不能把新左转换成等待，
        # 否则主板会一直沿用旧右转。真实主板故障仍由主板运动层处理。
        if self.continuous_control:return lane,control
        if self.pending is not None and self.sent_at is not None and now-self.sent_at>self.action_timeout:
            self.fault=True;self.ready=False
        waiting=(self.fault or not self.link_established or not self.ready or
                 self.pending is not None or now<self.settle_until)
        if waiting:
            lane=dict(lane);lane['state']='STRAIGHT' if lane['valid'] else 'LOST'
            control=dict(control);control.update(active=False,direction=0,angle=0.0,status=5,reason='WAIT_BOARD')
        return lane,control

    def sent(self,control,sequence,now):
        if self.continuous_control:return
        if self.enabled and control['active'] and self.pending is None:
            self.pending=sequence&255;self.sent_at=now;self.ready=False


"""Vision5.0：外框校正 + 内部图形模板；仅用 MicroPython 标准语法。
检测像素必须来自未画标记的灰度图。OpenCV 仅用于 PC 候选框回放。
"""
import math

SHAPE_NAMES = ('none', 'circle', 'star', 'square', 'diamond', 'plus', 'triangle')
# 图形与巡线阈值独立；多档灰度覆盖暗场和反光，最终使用卡片局部对比度。
CANDIDATE_THRESHOLDS = (55, 70, 85, 100, 115, 130)
GRID = 29


def candidate_ok(box, width=640, height=480):
    x,y,w,h = box
    return (40 <= w <= 280 and 38 <= h <= 280 and .55 < w/h < 1.8
            and x >= 0 and y >= 0 and x+w <= width and y+h <= height)


def board_candidates(img):
    boxes=[]
    for threshold in CANDIDATE_THRESHOLDS:
        # 全画面搜索：图形一进入视野就参与确认，不等到画面中间。
        blobs=img.find_blobs([(0,threshold)],roi=(0,0,640,480),
                             x_stride=2,y_stride=2,pixels_threshold=65,
                             area_threshold=1400,merge=False)
        for blob in blobs:
            box=blob.rect()
            if candidate_ok(box): boxes.append((box,threshold))
    return boxes


def _point_segment(x,y,a,b):
    dx,dy=b[0]-a[0],b[1]-a[1]
    t=max(0.,min(1.,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)))
    return math.sqrt((x-a[0]-t*dx)**2+(y-a[1]-t*dy)**2)


def _vertices(sid,r,phase=0.):
    if sid==2:
        return [(.5+ (r if i%2==0 else r*.43)*math.cos(-math.pi/2+phase+i*math.pi/5),
                 .5+ (r if i%2==0 else r*.43)*math.sin(-math.pi/2+phase+i*math.pi/5)) for i in range(10)]
    if sid==3:return [(.5-r,.5-r),(.5+r,.5-r),(.5+r,.5+r),(.5-r,.5+r)]
    if sid==4:return [(.5,.5-r),(.5+r,.5),(.5,.5+r),(.5-r,.5)]
    if sid==6:return [(.5,.5-r),(.5+r,.5+r),(.5-r,.5+r)]
    return []


def make_templates():
    result=[]
    for sid in range(1,7):
        for radius in (.32,.36,.40):
            # 五角星旋转72度后重合；四个18度相位覆盖卡片正放、倒放和横放。
            phases=(0.,math.pi/10,math.pi/5,math.pi*3/10) if sid==2 else (0.,)
            for phase in phases:
                vertices=_vertices(sid,radius,phase)
                pts=[]
                for y in range(GRID):
                    v=y/(GRID-1)
                    for x in range(GRID):
                        u=x/(GRID-1)
                        if not (.10<u<.90 and .10<v<.90):continue
                        if sid==1:dist=abs(math.sqrt((u-.5)**2+(v-.5)**2)-radius)
                        elif sid==5:
                            dist=min(_point_segment(u,v,(.5-radius,.5),(.5+radius,.5)),
                                     _point_segment(u,v,(.5,.5-radius),(.5,.5+radius)))
                        else:dist=min(_point_segment(u,v,vertices[i-1],vertices[i]) for i in range(len(vertices)))
                        if dist<.024:pts.append(y*GRID+x)
                near=set()
                for p in pts:
                    x,y=p%GRID,p//GRID
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):near.add((y+dy)*GRID+x+dx)
                result.append((sid,pts,near))
    return result


class CardRecognizer:
    def __init__(self):
        self.templates=make_templates()
        self.last_candidates=[]

    def classify(self,get_pixel,box,threshold):
        x,y,w,h=box
        # 外框是连通域的四个极值角；排除内图案不会改变极值。
        corners=[None]*4;ext=[1e9,-1e9,-1e9,1e9]
        for yy in range(y,y+h,2):
            for xx in range(x,x+w,2):
                if get_pixel(xx,yy)>threshold:continue
                a,b=xx+yy,xx-yy
                if a<ext[0]:ext[0]=a;corners[0]=(xx,yy)
                if b>ext[1]:ext[1]=b;corners[1]=(xx,yy)
                if a>ext[2]:ext[2]=a;corners[2]=(xx,yy)
                if b<ext[3]:ext[3]=b;corners[3]=(xx,yy)
        if None in corners:return None
        tl,tr,br,bl=corners
        edges=[math.sqrt((corners[i][0]-corners[i-1][0])**2+(corners[i][1]-corners[i-1][1])**2) for i in range(4)]
        if min(edges)<28 or max(edges)/min(edges)>1.65:return None
        # 四角双线性映射，补偿平面卡片旋转与中等透视。
        values=[]
        for gy in range(GRID):
            v=gy/(GRID-1)
            for gx in range(GRID):
                u=gx/(GRID-1)
                px=(1-v)*((1-u)*tl[0]+u*tr[0])+v*((1-u)*bl[0]+u*br[0])
                py=(1-v)*((1-u)*tl[1]+u*tr[1])+v*((1-u)*bl[1]+u*br[1])
                values.append(get_pixel(int(px+.5),int(py+.5)))
        ordered=sorted(values)
        dark,light=ordered[len(ordered)//10],ordered[len(ordered)*7//10]
        if light-dark<16:return None
        cut=dark+(light-dark)*.48
        # 外框四条边分别验真，机械结构、单独图案不能冒充完整卡片。
        sides=[]
        for side in range(4):
            hits=0
            for t in range(3,GRID-3):
                if side==0:ids=[d*GRID+t for d in range(3)]
                elif side==1:ids=[(GRID-1-d)*GRID+t for d in range(3)]
                elif side==2:ids=[t*GRID+d for d in range(3)]
                else:ids=[t*GRID+GRID-1-d for d in range(3)]
                hits+=min(values[p] for p in ids)<cut
            sides.append(hits/(GRID-6))
        if min(sides)<.60:return None
        observed=set(gy*GRID+gx for gy in range(3,GRID-3) for gx in range(3,GRID-3)
                     if values[gy*GRID+gx]<cut)
        if not 12<=len(observed)<=240:return None
        expanded=set()
        for p in observed:
            for dy in (-1,0,1):
                for dx in (-1,0,1):expanded.add(p+dy*GRID+dx)
        scores={}
        for sid,pts,near in self.templates:
            recall=sum(p in expanded for p in pts)/len(pts)
            precision=sum(p in near for p in observed)/len(observed)
            score=2*recall*precision/max(.001,recall+precision)
            scores[sid]=max(scores.get(sid,0),score)
        rank=sorted(scores,key=lambda sid:scores[sid],reverse=True)
        sid=rank[0];score=scores[sid];margin=score-scores[rank[1]]
        return dict(shape=sid,score=score,margin=margin,box=box,corners=corners,
                    accepted=score>=.82 and margin>=.065,scores=scores,contrast=light-dark)

    def detect(self,get_pixel,candidates):
        found=[]
        for box,threshold in candidates:
            result=self.classify(get_pixel,box,threshold)
            if result is not None:found.append(result)
        self.last_candidates=found
        accepted=[r for r in found if r['accepted']]
        if not accepted:return None
        return max(accepted,key=lambda r:r['score']+r['margin']*.3)


class ShapeEvents:
    """同一空间卡片连续确认；每个图形ID在本次运行中最多发送一次。"""
    def __init__(self):
        self.sent=set();self.queued=set()
        self.pending_id=0;self.hits=0;self.last_seen=None;self.box=None
        self.current=None

    def update(self,detection,now):
        self.current=detection
        if detection is None:
            self.pending_id=0;self.hits=0
            return 0
        sid=detection['shape'];box=detection['box']
        same=(sid==self.pending_id and self.last_seen is not None and now-self.last_seen<.65)
        if same and self.box is not None:
            same=abs(box[0]-self.box[0])+abs(box[1]-self.box[1])<max(box[2],box[3])*.8
        self.hits=self.hits+1 if same else 1
        self.pending_id=sid;self.last_seen=now;self.box=box
        if self.hits<2 or sid in self.queued or sid in self.sent:return 0
        self.queued.add(sid)
        return sid

    def mark_sent(self,sid,now):
        self.sent.add(sid);self.queued.discard(sid)


"""Independent long-bar detector. It never changes lane or shape results."""
import math


class ObstacleTracker:
    def __init__(self, confirm=3, clear=3):
        self.confirm=confirm;self.clear=clear
        self.hits=0;self.misses=0;self.present=False;self.angle=0.0

    def detect(self,img):
        # Work on the original VGA grayscale frame. Road borders are near vertical;
        # cards/cross shapes are too short. The obstacle must be a long near-horizontal bar.
        lines=img.find_lines(roi=(32,180,576,260),threshold=1500,
                             theta_margin=20,rho_margin=20)
        best=None
        for line in lines:
            dx=line.x2()-line.x1();dy=line.y2()-line.y1()
            length=(dx*dx+dy*dy)**0.5
            if length<260 or abs(dx)<1:continue
            angle=math.degrees(math.atan2(dy,dx))
            if angle>90:angle-=180
            if angle<-90:angle+=180
            if abs(angle)>35:continue
            middle=(line.y1()+line.y2())*.5
            if middle<190 or middle>430:continue
            score=length-abs(angle)*2
            if best is None or score>best[0]:best=(score,angle,(line.x1(),line.y1(),line.x2(),line.y2()))
        return None if best is None else dict(angle=best[1],line=best[2],score=best[0])

    def update(self,detection):
        if detection is None:
            self.hits=0;self.misses+=1
            if self.misses>=self.clear:self.present=False;self.angle=0.0
        else:
            self.misses=0;self.hits+=1
            # Low-pass only the bar angle; no data is fed into shape recognition.
            self.angle=detection['angle'] if self.hits==1 else self.angle*.6+detection['angle']*.4
            if self.hits>=self.confirm:self.present=True
        return dict(present=self.present,angle=self.angle if self.present else 0.0,
                    detection=detection)


def native_runs(img, y):
    blobs = img.find_blobs([(0, BLACK_MAX)], roi=(0, y, WIDTH, 1),
                           x_stride=1, y_stride=1, pixels_threshold=2,
                           area_threshold=2, merge=False)
    return sorted(b.x() + (b.w()-1)*0.5 for b in blobs
                  if max(2, WIDTH // 100) <= b.w() <= WIDTH*0.12)


def is_capture_error(exc):
    return isinstance(exc,RuntimeError) and "snapshot" in str(exc) and "failed(3)" in str(exc)


def capture_warmup(sensor):
    for frame in range(CAMERA_WARMUP_FRAMES):
        for attempt in range(CAMERA_WARMUP_RETRIES):
            os.exitpoint()
            try:
                warmup=sensor.snapshot()
                # 不保留上一个VB帧再请求下一个，及时释放采集缓冲。
                del warmup
                gc.collect()
                break
            except RuntimeError as exc:
                if not is_capture_error(exc):raise
                if attempt==0:print("CAMERA WARMUP retry frame",frame+1,exc)
                if attempt+1==CAMERA_WARMUP_RETRIES:raise
                gc.collect()
                time.sleep_ms(CAPTURE_RETRY_MS)


def reset_failed_camera():
    print("CAMERA recovery: persistent capture failure; resetting board")
    time.sleep_ms(100)
    machine.reset()
    # reset成功不返回；异常返回也不陷入无提示的无限等待。
    raise RuntimeError("Camera board reset unexpectedly returned")


def open_camera():
    """创建全新采集链路；部分初始化失败也按顺序释放。"""
    sensor = None
    sensor_running = display_inited = media_inited = False
    try:
        sensor = Sensor(width=SENSOR_MODE_WIDTH, height=SENSOR_MODE_HEIGHT)
        sensor.reset()
        sensor.set_framesize(Sensor.VGA)
        sensor.set_pixformat(Sensor.GRAYSCALE)
        # One capture only: sample every fourth pixel for the 160x120 grid.
        # Both flips together = 180 degrees, not a left/right-only mirror.
        sensor.set_hmirror(ROTATE_180)
        sensor.set_vflip(ROTATE_180)
        if PREVIEW:
            # Follow the board's one-minute-stable official camera example.
            # On firmware 0.4.0, VIRT may retain shared VB capture buffers.
            Display.init(Display.ST7701, width=640, height=480,
                         fps=DISPLAY_FPS, to_ide=True, quality=IDE_QUALITY)
            display_inited = True
        MediaManager.init()
        media_inited = True
        gc.collect()
        time.sleep_ms(CAMERA_PREPARE_MS)
        sensor_running = True
        sensor.run()
        # run后立即取帧，不让VB缓冲在第一个消费者前积压。
        capture_warmup(sensor)
        print("CAMERA WARMUP OK", CAMERA_WARMUP_FRAMES)
        return sensor
    except BaseException as exc:
        close_camera(sensor, sensor_running, display_inited, media_inited)
        if is_capture_error(exc) and AUTO_REBOOT_ON_CAMERA_FAILURE:
            reset_failed_camera()
        raise


def close_camera(sensor, sensor_running=True, display_inited=None, media_inited=True):
    # stop 在 MediaManager.deinit 之前；不能只对已 stop 的旧对象调用 run。
    if sensor_running and sensor is not None:
        try:
            sensor.stop()
        except Exception as exc:
            print("Camera stop:", exc)
    if display_inited is None:display_inited=PREVIEW
    if display_inited:
        try:
            Display.deinit()
        except Exception as exc:
            print("Camera display cleanup:", exc)
    gc.collect()
    time.sleep_ms(100)
    if media_inited:
        try:MediaManager.deinit()
        except Exception as exc:print("Camera media cleanup:",exc)
    gc.collect()
    time.sleep_ms(200)


def main():
    sensor = uart = None
    display_ready = media_ready = False
    print("VISION BUILD",BUILD_TAG,"UART RX",UART_RX_PIN)
    tracker = LaneTracker(threshold=0 if BINARY_DETECT else BLACK_MAX,
                          counterclockwise=COUNTERCLOCKWISE,
                          right_recover_enter=RIGHT_RECOVER_ENTER,
                          right_recover_exit=RIGHT_RECOVER_EXIT)
    angle_tracker = AngleTracker(enter=ANGLE_ENTER_DEG, leave=ANGLE_EXIT_DEG,
                                 confirm=ANGLE_CONFIRM_SECONDS, zero=ANGLE_ZERO_DEG)
    feedback = MotionFeedback(enabled=UART_RX_PIN is not None, continuous_control=True)
    result = dict(valid=False,stop=True,state="LOST",confidence=0,degraded=True,offset=0,heading=0,curvature=0,steer=0,mode="LOST",angle_source="NONE",position_direction=0)
    angle_result = dict(valid=False,active=False,direction=0,angle=0.0,status=0,reason="NO_EDGE")
    raw_angle_result = dict(angle_result)
    vision_result = dict(result)
    vision_angle_result = dict(angle_result)
    sequence = 0
    uart_tx_count = 0
    uart_last_tx_seq = None
    recognizer = CardRecognizer()
    shape_events = ShapeEvents()
    obstacle_tracker = ObstacleTracker(confirm=3,clear=3)
    obstacle_result = dict(present=False,angle=0.0,detection=None)
    shape_detection = None
    pending_shapes = []
    sent_shapes = {}
    try:
        # Start SENSOR2 first. UART/FPIOA setup is intentionally delayed until
        # the CSI2 pipeline is running, avoiding startup resource/pinmux races.
        sensor = open_camera()
        display_ready = PREVIEW
        media_ready = True
        if UART_TX_PIN is not None:
            mux = FPIOA()
            mux.set_function(UART_TX_PIN, FPIOA.UART1_TXD)
            if UART_RX_PIN is not None:
                mux.set_function(UART_RX_PIN, FPIOA.UART1_RXD)
            uart = UART(UART.UART1, baudrate=UART_BAUD, bits=UART.EIGHTBITS,
                        parity=UART.PARITY_NONE, stop=UART.STOPBITS_ONE)
        else:
            print("UART disabled: configure UART_TX_PIN for your board.")
        clock = time.clock()
        last_tick = time.ticks_ms()
        last_send = last_preview = last_stats = last_tick
        last_shape = last_obstacle = last_tick
        last_lane = None
        timestamp = 0.0
        frames = 0
        processing_us = 0
        lane_us = shape_us = shape_calls = shape_max_us = 0
        shape_max_id = 0
        display_fps = 0.0
        preview_hold = None  # Display may consume this copy asynchronously.
        capture_failures = 0
        consecutive_capture_failures = 0
        camera_restarts = stable_frames = 0
        while True:
            os.exitpoint()
            clock.tick()
            # 丢掉上一帧采集引用再取新帧；显示保留的是独立preview副本。
            img=None
            try:
                # Match the one-minute-stable official example exactly. The
                # default is channel 0; avoid the explicit chn path on 0.4.0.
                img = sensor.snapshot()
            except RuntimeError as exc:
                if not is_capture_error(exc):
                    raise
                angle_tracker.reset()
                last_lane = None
                stable_frames = 0
                capture_failures += 1
                consecutive_capture_failures += 1
                # Do not flood the IDE serial link while CSI2 is unavailable.
                if capture_failures in (1,CAPTURE_RETRIES):
                    print("CAPTURE retry %d/%d: %s" % (capture_failures, CAPTURE_RETRIES, exc))
                tracker = LaneTracker(threshold=0 if BINARY_DETECT else BLACK_MAX,
                                      counterclockwise=COUNTERCLOCKWISE,
                                      right_recover_enter=RIGHT_RECOVER_ENTER,
                                      right_recover_exit=RIGHT_RECOVER_EXIT)
                if uart is not None:
                    uart.write(encode(dict(valid=False, stop=True, state="LOST"), sequence))
                    uart.write(encode_angle(dict(valid=False, active=False, angle=0), sequence))
                    sequence = (sequence+1) & 255
                # Do not allocate/show a warning frame here: Display may still
                # retain VB buffers and make capture recovery harder. Keep the
                # last valid IDE preview and report progress in the terminal.
                gc.collect()
                if (AUTO_REBOOT_ON_CAMERA_FAILURE and
                        consecutive_capture_failures >= CAMERA_REBOOT_FAILURES):
                    reset_failed_camera()
                if capture_failures >= CAPTURE_RETRIES:
                    if not CAMERA_REBUILD:
                        print("CAMERA still unavailable; keep retrying without rebuild")
                        capture_failures = 0
                        time.sleep_ms(CAPTURE_RETRY_MS)
                        continue
                    if camera_restarts >= CAMERA_RESTART_LIMIT:
                        print("CAMERA recovery exhausted; check power/cable/firmware")
                        raise
                    camera_restarts += 1
                    print("CAMERA rebuild %d/%d" % (camera_restarts, CAMERA_RESTART_LIMIT))
                    close_camera(sensor)
                    sensor = None
                    display_ready = media_ready = False
                    sensor = open_camera()
                    display_ready = PREVIEW
                    media_ready = True
                    capture_failures = 0
                    # 保留图形冷却、待发送队列与串口序号。
                time.sleep_ms(CAPTURE_RETRY_MS)
                continue
            capture_failures = 0
            consecutive_capture_failures = 0
            stable_frames += 1
            if stable_frames >= 30:
                camera_restarts = 0
            now = time.ticks_ms()
            delta = time.ticks_diff(now, last_tick)
            if delta <= 0:
                continue
            timestamp += delta / 1000.0  # Accumulation survives ticks wraparound.
            last_tick = now
            before = time.ticks_us()
            if BINARY_DETECT:
                # Selected dark pixels stay 0, background becomes 255.
                img.binary([(0, BLACK_MAX)], invert=True)
            if uart is not None and UART_RX_PIN is not None:
                if uart.any():
                    feedback.feed(uart.read(min(uart.any(),64)),timestamp)
                if feedback.reset_heading:
                    angle_tracker.reset()
                    feedback.reset_heading=False
                    last_lane=None
            lane_before = time.ticks_us()
            if last_lane is None or time.ticks_diff(now,last_lane)>=LANE_PERIOD_MS:
                last_lane=now
                lane_result=tracker.update(lambda x,y:img.get_pixel(x*4,y*4),WIDTH,HEIGHT,timestamp)
                raw_angle_result=angle_tracker.update(tracker.raw_image_angle,timestamp)
                result,angle_result=resolve_control(lane_result,raw_angle_result)
                if angle_result['active'] and angle_result['reason']=='CURVE':
                    tracker.remember_turn(angle_result['direction'],timestamp,
                                          angle_result['angle'])
                # Position recovery suppresses stale opposite heading evidence.
                if angle_result['reason']=='POSITION':angle_tracker.reset()
                vision_result,vision_angle_result=result,angle_result
            # Keep the raw visual decision separate from the UART feedback gate.
            result,angle_result=feedback.gate(vision_result,vision_angle_result,timestamp)
            lane_us += time.ticks_diff(time.ticks_us(), lane_before)
            # 使用原始灰度帧，独立多阈值检测，不再跟随巡线阈值。
            if SHAPE_DETECT and time.ticks_diff(now, last_shape) >= SHAPE_PERIOD_MS:
                last_shape = now
                shape_before = time.ticks_us()
                boxes = board_candidates(img)
                shape_detection = recognizer.detect(img.get_pixel, boxes)
                event = shape_events.update(shape_detection, timestamp)
                if event and event not in pending_shapes:
                    pending_shapes.append(event)
                    sent_shapes.pop(event, None)
                    print("SHAPE %d CONFIRMED score %.3f" % (event, shape_detection['score']))
                one_shape_us = time.ticks_diff(time.ticks_us(), shape_before)
                shape_us += one_shape_us
                shape_calls += 1
                if one_shape_us > shape_max_us:
                    shape_max_us = one_shape_us
                    shape_max_id = 0
                del boxes
            # 障碍检测读取同一张原始灰度图，但与图形分类没有共享阈值、候选或状态。
            if time.ticks_diff(now,last_obstacle)>=OBSTACLE_PERIOD_MS:
                last_obstacle=now
                obstacle_result=obstacle_tracker.update(obstacle_tracker.detect(img))
            processing_us += time.ticks_diff(time.ticks_us(), before)
            frames += 1
            if uart is not None and time.ticks_diff(now, last_send) >= UART_PERIOD_MS:
                shape_event = pending_shapes[0] if pending_shapes else 0
                packet = encode(result, sequence, shape_id=shape_event)
                if uart.write(packet) != len(packet):
                    raise OSError("UART incomplete write")
                # 旧图形包成功后立即记账，附加角度包异常也不会重发图形。
                sequence = (sequence + 1) & 255
                last_send = now
                if shape_event:
                    sent_shapes[shape_event] = True
                    shape_events.mark_sent(shape_event, timestamp + time.ticks_diff(time.ticks_ms(), now)/1000.0)
                    pending_shapes.pop(0)  # Each queued event occupies one packet.
                angle_packet = encode_angle(angle_result, (sequence-1)&255)
                if uart.write(angle_packet) != len(angle_packet):
                    raise OSError("UART angle incomplete write")
                obstacle_packet=encode_obstacle(obstacle_result,(sequence-1)&255)
                if uart.write(obstacle_packet)!=len(obstacle_packet):
                    raise OSError("UART obstacle incomplete write")
                uart_tx_count += 3
                uart_last_tx_seq = (sequence-1)&255
                feedback.sent(angle_result,(sequence-1)&255,timestamp)
            # Future shape recognition goes here, BEFORE drawing debug overlays.
            # Schedule it at a lower rate; do not run full-frame contours every frame.
            if PREVIEW and time.ticks_diff(now, last_preview) >= PREVIEW_PERIOD_MS:
                # Never hand a Sensor/VB capture frame to asynchronous Display.
                # Retain only the newest heap copy until the next preview.
                preview_img = img.copy()
                if BINARY_VISIBLE and not BINARY_DETECT:
                    preview_img.binary([(0, BLACK_MAX)], invert=BINARY_INVERT)
                for y, left, right in tracker.rows:
                    preview_img.draw_cross(int(left*4), y*4, color=127, size=4)
                    preview_img.draw_cross(int(right*4), y*4, color=127, size=4)
                    preview_img.draw_cross(int((left+right)*2), y*4, color=127, size=6)
                state = vision_result["state"] if vision_result["valid"] else "LOST"
                labels = {"STRAIGHT": "直走", "LEFT": "向左修正",
                          "RIGHT": "向右修正", "LOST": "边界不确定"}
                preview_img.draw_rectangle(0, 0, 640, 124, color=0, fill=True)
                preview_img.draw_string_advanced(8, 2, 28, "视觉判定：" + labels[state] + "  " + BUILD_TAG,
                                                 color=(255, 255, 255))
                mode = {"BOTH":"双边","SINGLE_LEFT":"左单边","SINGLE_RIGHT":"右单边","UNCERTAIN":"边界不确定","LOST":"未找到边界"}.get(vision_result["mode"],"巡线")
                if shape_detection is not None:
                    sid = shape_detection['shape']
                    mode = "图形%d 分数%.2f / %s" % (sid, shape_detection['score'],
                              "已发送" if sent_shapes.get(sid) else "连续确认中")
                    bx,by,bw,bh = shape_detection['box']
                    preview_img.draw_rectangle(bx,by,bw,bh,color=255,thickness=2)
                elif pending_shapes:
                    mode = "图形%d已确认 / 等待串口发送" % pending_shapes[0]
                if obstacle_result['present']:
                    mode += " / 障碍角%+.1f度" % obstacle_result['angle']
                road = "左弯" if vision_result.get('road_shape')=='LEFT_CURVE' else "直线"
                mode += " / %s C:%+.3f H:%+.3f" % (road,vision_result.get('curvature',0),vision_result.get('heading',0))
                preview_img.draw_string_advanced(8, 38, 21, mode,
                                                 color=(255, 255, 255))
                if angle_result['reason']=='POSITION':
                    angle_text='下发：位置避边 / '+('向右' if angle_result['direction']>0 else '向左')
                elif angle_result['reason']=='TURN_MEMORY':
                    angle_text='下发：保持已确认左转'
                elif angle_result['reason']=='LOSS_HOLD':
                    angle_text='下发：短时丢线 / 保持左转'
                elif angle_result['reason']=='WAIT_BOARD':
                    angle_text='下发：等待主板完成'
                elif raw_angle_result['valid']:
                    angle_text='下发：%s / 偏角%+.1f度' % (labels[result['state']],raw_angle_result['angle'])
                else:
                    angle_text='下发：单边位置判断' if result['valid'] else '下发：边界证据不足'
                angle_text += "  FPS:%.1f" % display_fps
                preview_img.draw_string_advanced(8,68,20,angle_text,color=(255,255,255))
                preview_img.draw_rectangle(0,442,640,38,color=0,fill=True)
                preview_img.draw_string_advanced(8,446,21,"图形：独立灰度 / 外框校正 / 连续确认",color=(255,255,255))
                link=feedback.link_status(timestamp)
                rx_age='--' if feedback.last_link_rx is None else '%.1fs'%(timestamp-feedback.last_link_rx)
                tx_seq='--' if uart_last_tx_seq is None else str(uart_last_tx_seq)
                rx_seq='--' if feedback.last_seq is None else str(feedback.last_seq)
                rx_state='--' if feedback.last_state is None else str(feedback.last_state)
                pending='--' if feedback.pending is None else str(feedback.pending)
                uart_text='LINK:%s TX:%d Q%s RX:%d Q%s ST:%s P:%s %s B:%d' % (
                    link,uart_tx_count,tx_seq,feedback.valid_packets,rx_seq,
                    rx_state,pending,rx_age,feedback.bad_packets)
                preview_img.draw_string_advanced(8,94,17,uart_text,color=(255,255,255))
                Display.show_image(preview_img, x=round((640-sensor.width())/2),
                                   y=round((480-sensor.height())/2))
                old_preview = preview_hold
                preview_hold = preview_img
                del old_preview
                last_preview = now
                # Do not delete preview_hold: Display may still be reading it.
            elapsed = time.ticks_diff(now, last_stats)
            if elapsed >= 1000:
                display_fps = frames*1000/elapsed
                if PRINT_STATS:
                    perf_phase = "target" if shape_detection is not None else "search"
                    print("FPS %.1f algo %.2fms lane %.2fms shape %.2fms max %.2fms "
                          "phase=%s %s valid=%d conf=%.2f steer=%.2f" %
                          (frames*1000/elapsed, processing_us/frames/1000,
                           lane_us/frames/1000,
                           shape_us/max(1, shape_calls)/1000, shape_max_us/1000,
                           perf_phase,
                           result["state"], result["valid"], result["confidence"], result["steer"]))
                frames = processing_us = lane_us = shape_us = shape_calls = 0
                shape_max_us = shape_max_id = 0
                last_stats = now
                gc.collect()
    except KeyboardInterrupt as exc:
        print("user stop:", exc)
    except BaseException as exc:
        sys.print_exception(exc)
    finally:
        # 退出时发送无效视觉数据；主板沿用现有丢线控制策略。
        if uart is not None:
            try:
                uart.write(encode(dict(valid=False, stop=True, state="LOST",
                                       offset=0, heading=0, steer=0, confidence=0), sequence))
                uart.write(encode_angle(dict(valid=False, active=False, angle=0), sequence))
            except Exception as exc:
                print("UART stop packet:", exc)
            try:
                uart.deinit()
            except Exception as exc:
                print("UART cleanup:", exc)
        if sensor is not None:
            try:
                sensor.stop()
            except Exception as exc:
                print("Sensor cleanup:", exc)
        if display_ready:
            try:
                Display.deinit()
            except Exception as exc:
                print("Display cleanup:", exc)
        os.exitpoint(os.EXITPOINT_ENABLE_SLEEP)
        time.sleep_ms(100)
        if media_ready:
            try:MediaManager.deinit()
            except Exception as exc:print("Media cleanup:",exc)


main()
